/* Family settings review only. No native settings or persistence. */
(function(){
'use strict';
const controls=[...document.querySelectorAll('[data-control]')],settings=[...document.querySelectorAll('[data-setting]')],frames=[...document.querySelectorAll('iframe[data-layout]')],target=document.getElementById('customize-family');
const defaults=Object.fromEntries(settings.map(control=>[control.dataset.setting,control.value]));
const actionLabels={'vote-up':'Upvote','vote-down':'Downvote','post-details':'Comments','external':'Open externally','save':'Save','share-post':'Share','copy-link':'Copy link'};
function defaultsFor(family){return {...defaults,'layout-toolbar':(family==='compact'?['vote-up','vote-down','post-details','external']:['vote-up','vote-down','post-details','save','share-post']).join(','),...(['large','compact'].includes(family)?{'layout-surface':'filled'}:{}),...(family==='gallery'?{'layout-gallery':'media'}:{})}}
const familySettings=Object.fromEntries(frames.map(frame=>[frame.dataset.layout,defaultsFor(frame.dataset.layout)]));
const notes={large:'Large card defaults to Card 1 + Filled, Fit whole media and a toolbar below content. Card 2, Square crop, Above, Outlined and Flat remain selectable. Save as layout keeps a named copy of your configuration.',compact:'Compact card defaults to Filled; Outlined and Flat remain selectable. The accepted hidden customizable toolbar remains. Hold a row or press Shift+F10; use More → Customize toolbar.',vertical:'Vertical swipe: remains vertical; Horizontal is available only after Gallery entry. The accepted media behavior is reused. Media-specific settings will be reviewed separately; card controls do not apply here.',gallery:'Gallery defaults to visual media only, at least two columns and Fit whole media scaled to each tile. All posts remains selectable. Tap a visual tile for the media-first viewer: Horizontal by default, Vertical selectable. Swipes step through album images before the next visual post. Other tiles open details; Back keeps the current tile visible.'};
const savedLayouts=[],selectedByFamily=new Map(),library=document.getElementById('saved-layouts'),dialog=document.getElementById('save-layout-dialog'),nameInput=document.getElementById('layout-name'),libraryStatus=document.getElementById('layout-library-status');
let nextLayoutId=1,saveSnapshot=null;
function applies(control,family){return control.dataset.families.split(' ').includes(family)}
function send(frame){const family=frame.dataset.layout,values=Object.fromEntries(controls.map(control=>[control.dataset.control,control.value]));for(const control of settings)if(applies(control,family))values[control.dataset.setting]=familySettings[family][control.dataset.setting];frame.contentWindow?.postMessage({type:'relaxe-layout-comparison',values},location.origin)}
function update(){const width=document.getElementById('compare-width').value;document.documentElement.style.setProperty('--comparison-width',width+'px');for(const frame of frames){frame.style.height=({360:800,390:844,600:960,720:480,840:960,1280:960}[width]||844)+'px';send(frame)}}
const capacities=new Map(),toolbarCapacities=new Map();
function showToolbarCapacity(){const state=toolbarCapacities.get(target.value);document.getElementById('toolbar-capacity-status').textContent=state?`Current rows fit ${state.min===state.max?state.min:state.min+'–'+state.max} selected actions plus More. Lower-priority actions stay in More; saved order is retained.`:'Selected icons are a priority order. The toolbar shows only those that fit in one row, plus More. Reveal the Compact toolbar to inspect its capacity.'}
function showCapacity(){const state=capacities.get(target.value),control=settings.find(control=>control.dataset.setting==='layout-columns');control.disabled=Boolean(state&&state.capacity<2);control.querySelector('option[value="1"]').disabled=target.value==='gallery';document.getElementById('column-status').textContent=state&&target.value==='gallery'?`Showing ${state.effective} columns at ${state.width}px. Gallery keeps at least two columns, including narrow windows; whole-media previews scale down to fit.`:state&&target.value==='large'?`Showing ${state.effective} column${state.effective===1?'':'s'} at ${state.width}px. Wide-window preference is retained when space is limited.`:'Compact card and Vertical swipe use one column in this study.'}
function draft(){selectedByFamily.delete(target.value);renderLibrary();libraryStatus.textContent='Unsaved changes. Saved layouts are unchanged.';send(frames.find(frame=>frame.dataset.layout===target.value))}
function renderToolbar(focusKey){const family=target.value,editor=document.getElementById('toolbar-editor');editor.hidden=!['large','compact'].includes(family);const list=document.getElementById('toolbar-actions');list.replaceChildren();if(editor.hidden)return;const order=familySettings[family]['layout-toolbar'].split(',').filter(Boolean),ids=[...order,...Object.keys(actionLabels).filter(id=>!order.includes(id))];for(const id of ids){const row=document.createElement('div');row.className='toolbar-editor-row';const label=document.createElement('label'),check=document.createElement('input');check.type='checkbox';check.checked=order.includes(id);check.dataset.focus=id;label.append(check,document.createTextNode(actionLabels[id]));row.append(label);check.addEventListener('change',()=>{const next=check.checked?[...order,id]:order.filter(item=>item!==id);setToolbar(next,id)});for(const [direction,delta]of [['Up',-1],['Down',1]]){const button=document.createElement('button');button.type='button';button.textContent=direction;button.setAttribute('aria-label',`Move ${actionLabels[id]} ${direction.toLowerCase()}`);button.dataset.focus=id+'-'+direction;const index=order.indexOf(id);button.disabled=index<0||index+delta<0||index+delta>=order.length;button.addEventListener('click',()=>{const next=[...order];[next[index],next[index+delta]]=[next[index+delta],next[index]];setToolbar(next,id+'-'+direction)});row.append(button)}list.append(row)}if(focusKey){const control=[...list.querySelectorAll('[data-focus]')].find(control=>control.dataset.focus===focusKey);(control?.disabled?list.querySelector(`input[data-focus="${focusKey.replace(/-(Up|Down)$/,'')}"]`):control)?.focus()}}
function setToolbar(order,focusKey){familySettings[target.value]['layout-toolbar']=order.join(',');document.getElementById('toolbar-value').value=order.join(',');if(target.value==='large'){familySettings.large['layout-actions']='source';settings.find(control=>control.dataset.setting==='layout-actions').value='source'}draft();renderToolbar(focusKey)}
function renderLibrary(){const placeholder=document.createElement('option');placeholder.value='';placeholder.textContent='Current customizations';library.replaceChildren(placeholder);for(const saved of savedLayouts.filter(item=>item.family===target.value)){const option=document.createElement('option');option.value=saved.id;option.textContent=saved.name;library.append(option)}library.value=selectedByFamily.get(target.value)||''}
function showSettings(){for(const control of settings){control.value=familySettings[target.value][control.dataset.setting];const label=control.closest('label');if(label)label.hidden=!applies(control,target.value)}document.getElementById('family-settings-note').textContent=notes[target.value];document.getElementById('reset-comparison').hidden=target.value==='vertical';renderLibrary();renderToolbar();showCapacity();showToolbarCapacity()}
for(const control of controls)control.addEventListener('change',update);
for(const control of settings)control.addEventListener('change',()=>{familySettings[target.value][control.dataset.setting]=control.value;draft()});
window.addEventListener('message',event=>{if(event.origin!==location.origin)return;const frame=frames.find(frame=>frame.contentWindow===event.source);if(!frame)return;const state=event.data;if(state?.type==='relaxe-toolbar-capacity'&&Number.isInteger(state.min)&&Number.isInteger(state.max)&&state.min>=0&&state.max<=7&&state.min<=state.max){const old=toolbarCapacities.get(frame.dataset.layout);if(!old||old.min!==state.min||old.max!==state.max){toolbarCapacities.set(frame.dataset.layout,state);if(target.value===frame.dataset.layout)showToolbarCapacity()}}if(state?.type==='relaxe-layout-capacity'&&[1,2].includes(state.capacity)&&[1,2].includes(state.effective)){capacities.set(frame.dataset.layout,state);showCapacity()}if(state?.type==='relaxe-toolbar-state'&&frame.dataset.layout==='compact'&&typeof state.toolbar==='string'&&state.toolbar.split(',').filter(Boolean).every(id=>Object.hasOwn(actionLabels,id))&&['always','hidden'].includes(state.visibility)){const config=familySettings.compact;if(config['layout-toolbar']===state.toolbar&&config['layout-toolbarvisibility']===state.visibility)return;config['layout-toolbar']=state.toolbar;config['layout-toolbarvisibility']=state.visibility;selectedByFamily.delete('compact');if(target.value==='compact'){showSettings();libraryStatus.textContent='Toolbar draft updated from the Compact preview. Saved layouts are unchanged.'}}});
target.addEventListener('change',showSettings);
for(const frame of frames)frame.addEventListener('load',()=>send(frame));
for(const button of document.querySelectorAll('[data-reveal-layout]'))button.addEventListener('click',()=>frames.find(frame=>frame.dataset.layout===button.dataset.revealLayout)?.closest('.comparison-panel').scrollIntoView({block:'nearest',inline:'start'}));
document.getElementById('reset-comparison').addEventListener('click',()=>{familySettings[target.value]=defaultsFor(target.value);selectedByFamily.delete(target.value);showSettings();libraryStatus.textContent='Family defaults restored. Saved layouts are kept.';send(frames.find(frame=>frame.dataset.layout===target.value))});
library.addEventListener('change',()=>{const saved=savedLayouts.find(item=>item.id===library.value&&item.family===target.value);if(!saved){selectedByFamily.delete(target.value);libraryStatus.textContent='Current settings kept as a draft.';return}familySettings[target.value]={...defaultsFor(target.value),...saved.settings};selectedByFamily.set(target.value,saved.id);showSettings();libraryStatus.textContent='Applied “'+saved.name+'”. Edit it or save another named copy.';send(frames.find(frame=>frame.dataset.layout===target.value))});
document.getElementById('save-as-layout').addEventListener('click',()=>{saveSnapshot={family:target.value,settings:Object.fromEntries(settings.filter(control=>applies(control,target.value)).map(control=>[control.dataset.setting,control.value]))};nameInput.value='';nameInput.removeAttribute('aria-invalid');document.getElementById('layout-name-error').textContent='';document.getElementById('save-layout-family').textContent='Based on '+target.selectedOptions[0].textContent;dialog.returnValue='';dialog.showModal();nameInput.focus()});
document.getElementById('cancel-save-layout').addEventListener('click',()=>dialog.close('cancel'));
document.getElementById('save-layout-form').addEventListener('submit',event=>{event.preventDefault();const name=nameInput.value.trim();let error='';if(!name)error='Enter a layout name.';else if(name.length>64)error='Use 64 characters or fewer.';else if(savedLayouts.some(item=>item.family===saveSnapshot.family&&item.name.toLowerCase()===name.toLowerCase()))error='That name is already used in this family. Choose a new name.';if(error){document.getElementById('layout-name-error').textContent=error;nameInput.setAttribute('aria-invalid','true');nameInput.focus();return}const saved={id:'custom-'+nextLayoutId++,version:1,name,...saveSnapshot,settings:{...saveSnapshot.settings}};savedLayouts.push(saved);selectedByFamily.set(saved.family,saved.id);renderLibrary();libraryStatus.textContent='Saved “'+name+'” in this preview. Reloading clears preview layouts.';dialog.close('saved')});
dialog.addEventListener('close',()=>document.getElementById(dialog.returnValue==='saved'?'saved-layouts':'save-as-layout').focus());
dialog.addEventListener('keydown',event=>{if(event.key!=='Tab')return;const controls=[...dialog.querySelectorAll('input,button')].filter(control=>!control.disabled),first=controls[0],last=controls[controls.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}});
showSettings();
})();
